python3 -W ignore -c "
import cobra, logging, re; logging.disable(logging.CRITICAL)
m=cobra.io.read_sbml_model('data/models/kphaffii_imt1026v3/iMT1026v3.xml')
pats={'GDP-mannose':r'gdpmann|gdp.?man','UDP-GlcNAc':r'uacgam|udpacgal|acgam','UDP-glucose':r'^udpg','dolichol':r'dolich|dolp|dolmanp','heme':r'pheme|heme|hemeA|sheme','protoporphyrin':r'ppp9|protoporph','ALA':r'5aop|alav','glutathione':r'gthrd|gthox','FAD':r'^fad','H2O2':r'h2o2','SAM':r'amet|ahcys','ATP/GTP':r'^(atp|gtp|adp|gdp|amp|ppi)_','phosphoserine':r'pser','mannose':r'^man[0-9]*_|man1p|man6p'}
for k,p in pats.items():
    hits=[(x.id,x.name) for x in m.metabolites if re.search(p,x.id,re.I)]
    print(f'== {k}  ({len(hits)})')
    for h in hits[:14]: print('    ',h[0],'|',h[1])
" 2>&1 | grep -v Encoding

