print('--- pheme transport/use ---')
for r in m.metabolites.get_by_id('pheme_m').reactions: print(' ',r.id,'|',r.name,'|',r.reaction[:150])
print()
print('--- formulas sample ---')
for i in ['ala_L_c','trp_L_c','gdpmann_c','uacgam_c']:
    x=m.metabolites.get_by_id(i); print(' ',i,x.formula,x.charge)
" 2>&1 | grep -v Encoding

