import logging, cobra, sys; logging.disable(logging.CRITICAL)
m=cobra.io.read_sbml_model('data/models/kphaffii_imt1026v3/iMT1026v3.xml')
for i in ['atp_c','adp_c','pi_c','h_c','h2o_c','gtp_c','gdp_c','amp_c','nadph_c','nadp_c','o2_c','h2o2_c','uacgam_c','udp_c','gdpmann_c','udpg_c','glc_D_c','pheme_m']:
    x=m.metabolites.get_by_id(i); print(f'{i:12s} {x.formula}  charge={x.charge}')
print()
# check an existing known-balanced reaction
for rid in ['ATPM','HEX1','PGI']:
    try:
        r=m.reactions.get_by_id(rid); print(rid, r.reaction, '->', r.check_mass_balance())
    except Exception as e: print(rid,'ERR',e)
" 2>&1 | grep -v Encoding

