 * viva, so it is set for a screen rather than for paper: one comfortable
 * measure in the middle of the window, a serif body, sans-serif headings to
 * match the Word build, and a dark mode that follows the reader's system
 * setting. Everything is in this one file and embedded by pandoc, so the
 * HTML stays a single portable document with no network dependency.
 */

:root {
  --ink: #1a1a1a;
  --ink-soft: #555;
