  font-size: 0.9rem;
  color: var(--ink-soft);
  line-height: 1.45;
  margin-top: 0.6em;
}

blockquote {
  margin: 1.2em 0;
  padding-left: 1em;
  border-left: 3px solid var(--rule);
  color: var(--ink-soft);
}

code, pre { font-family: var(--mono); font-size: 0.88em; }
code { background: var(--code-bg); padding: 0.1em 0.3em; border-radius: 3px; }
pre { background: var(--code-bg); padding: 0.9em 1em; overflow-x: auto; border-radius: 4px; }
