hr { border: 0; border-top: 1px solid var(--rule); margin: 2.4em 0; }

/* The contents list, which pandoc writes as a nested nav. */
nav#TOC {
  font-family: var(--head);
  font-size: 0.95rem;
  line-height: 1.5;
